export interface LibraryShape {
  /** display name in the picker */
  l: string;
  /** genre */
  g: ShapeGenre;
  /** free-text search keywords, space separated. Never displayed. */
  t: string;
  /** the node DSL above */
  d: string;
  /** 1 = closed geometry, takes the object's fill; 0 = line art, stroke only */
  f: 0 | 1;
}

